INSERT INTO press_offers VALUES
 ('PRESS-0001', (SELECT country_code FROM countries WHERE country_iso3 = 'COL'), (SELECT platform_id FROM platforms WHERE platform_name = 'TikTok'), 'seguridad privada, logística, construcción o cocina', 2400, 'USD', 'mensual', NULL, 'Federación Rusa', NULL, NULL, 'Anuncios en TikTok, Facebook y Telegram prometen empleo civil en Rusia con sueldo de 2,400 a 2,600 USD y bono inicial de 25,000 a 50,000 USD; terminan en el frente.', NULL, FALSE, 'other', 'high', 1),
 ('PRESS-0002', (SELECT country_code FROM countries WHERE country_iso3 = 'MEX'), NULL, 'empleos en EE.UU. o Canadá, castings y trabajos temporales', 12000, 'MXN', NULL, NULL, 'Estados Unidos o Canadá; otras ciudades', 'jóvenes que buscan trabajo fuera del estado o en el extranjero', NULL, 'En Oaxaca circulan anuncios de empleo en EE.UU./Canadá, castings o trabajos temporales con pagos de hasta 12 mil pesos, para atraer jóvenes a trabajo forzado.', NULL, TRUE, NULL, 'medium', 1),
 ('PRESS-0004', (SELECT country_code FROM countries WHERE country_iso3 = 'MEX'), NULL, 'supuestas citas de trabajo (anuncios en internet)', NULL, NULL, NULL, NULL, NULL, 'hombres jóvenes', NULL, '11 personas de Amozoc, en su mayoría hombres jóvenes, respondieron anuncios en internet, acudieron a citas de trabajo y fueron reclutadas por un grupo delictivo.', 'ForcedCriminalityScheme', TRUE, 'rescate', 'medium', 1),
 ('PRESS-0005', NULL, NULL, 'trabajos de construcción', 204000, 'RUB', 'mensual', NULL, 'Rusia', NULL, NULL, 'Cubanos atraídos por anuncios de trabajo de construcción en Rusia, con salario de hasta 204,000 rublos al mes y promesa de pasaporte ruso, terminan en el ejército en Ucrania.', NULL, FALSE, 'other', 'medium', 1),
 ('PRESS-0006', (SELECT country_code FROM countries WHERE country_iso3 = 'MEX'), NULL, 'guardia de seguridad', 4000, 'MXN', 'semanal', 4000, NULL, 'jóvenes', NULL, 'Falsas ofertas de guardia de seguridad en redes sociales con pagos semanales de 4 mil hasta 12 mil pesos para captar jóvenes para el cártel.', 'ForcedCriminalityScheme', TRUE, 'detencion_reclutador', 'high', 1),
 ('PRESS-0007', (SELECT country_code FROM countries WHERE country_iso3 = 'MEX'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Redim señala como modalidad de engaño las falsas ofertas de empleo hechas en espacios públicos como centros comerciales y tiendas de conveniencia.', 'InPersonLureScheme', TRUE, NULL, 'low', 1),
 ('PRESS-0008', (SELECT country_code FROM countries WHERE country_iso3 = 'MEX'), NULL, 'mesera o agente de seguridad', NULL, NULL, NULL, NULL, 'México', NULL, NULL, 'Sobrevivientes confiaron en ofertas de trabajo con sueldos atractivos como meseras o agentes de seguridad y terminaron aisladas, trabajando sin descanso en campos o casas, sin teléfono.', NULL, FALSE, 'explotacion_laboral', 'medium', 1),
 ('PRESS-0009', (SELECT country_code FROM countries WHERE country_iso3 = 'COL'), (SELECT platform_id FROM platforms WHERE platform_name = 'TikTok'), 'empleo, beca o casting; trabajo en España', NULL, 'EUR', NULL, NULL, 'España', 'mujeres y niñas', NULL, 'Mujeres y niñas colombianas reciben por TikTok, Instagram y WhatsApp ofertas de empleo, becas y castings, o ven a una amiga ganando en euros en España; son fachadas de trata.', NULL, FALSE, 'explotacion_sexual', 'low', 1),
 ('PRESS-0010', (SELECT country_code FROM countries WHERE country_iso3 = 'MEX'), NULL, 'falsa oferta de trabajo en Sinaloa', NULL, NULL, NULL, NULL, 'Sinaloa', 'adolescente de 15 y joven de 20 años', NULL, 'Dos jóvenes jaliscienses, de 15 y 20 años, escaparon de una falsa oferta laboral en Sinaloa y fueron localizados en la central camionera de Tlaquepaque.', 'ChildRecruitmentCriminalScheme', TRUE, 'rescate', 'low', 1),
 ('PRESS-0011', (SELECT country_code FROM countries WHERE country_iso3 = 'MEX'), NULL, 'falsa oferta laboral (campamento en Zacatecas)', 5000, 'MXN', 'semanal', 5000, NULL, 'jóvenes, entre ellos menores', NULL, 'Jóvenes michoacanos engañados con oferta de 5 mil pesos semanales fueron citados en la central camionera de Guadalajara para llevarlos a un campamento del CJNG en Zacatecas.', 'ChildRecruitmentCriminalScheme', TRUE, 'detencion_reclutador', 'high', 1),
 ('PRESS-0012', (SELECT country_code FROM countries WHERE country_iso3 = 'MEX'), NULL, 'guardia de seguridad', 12000, 'MXN', 'semanal', 12000, NULL, NULL, NULL, '''El Lastra'' ofrecía por redes sociales empleos de guardia de seguridad con pagos semanales de hasta 12 mil pesos y llevaba a los interesados al Rancho Izaguirre a entrenamiento.', 'ForcedCriminalityScheme', TRUE, 'detencion_reclutador', 'high', 1),
 ('PRESS-0013', NULL, (SELECT platform_id FROM platforms WHERE platform_name = 'Telegram'), 'trabajo remoto muy sencillo', NULL, NULL, NULL, NULL, NULL, NULL, 'ha llamado la atención de varios reclutadores en línea', 'Mensaje de una supuesta profesional de InfoJobs ofrece puesto remoto con salario muy alto por un trabajo muy sencillo y pide contactar por Telegram; es falso.', NULL, FALSE, 'fraude_economico', 'medium', 1),
 ('PRESS-0014', (SELECT country_code FROM countries WHERE country_iso3 = 'MEX'), NULL, 'oferta de trabajo en Jalisco', NULL, NULL, NULL, NULL, 'Jalisco', 'hombres, uno menor de edad', NULL, '10 hombres de Amozoc acudieron a una supuesta oferta de trabajo en Jalisco, vestidos de playera negra y mezclilla como pedía la oferta, y desaparecieron del 8 al 11 de agosto.', NULL, FALSE, 'desaparicion', 'medium', 1),
 ('PRESS-0015', (SELECT country_code FROM countries WHERE country_iso3 = 'ARG'), (SELECT platform_id FROM platforms WHERE platform_name = 'WhatsApp'), 'reseñas de Google Maps (medio tiempo)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Estafa por WhatsApp con nombre de Google Maps: trabajo de medio tiempo haciendo reseñas de hoteles desde el móvil, con comisión que se cobra tras pasar a Telegram.', NULL, FALSE, 'fraude_economico', 'high', 3),
 ('PRESS-0016', (SELECT country_code FROM countries WHERE country_iso3 = 'ARG'), (SELECT platform_id FROM platforms WHERE platform_name = 'WhatsApp'), 'clics en enlaces de YouTube (medio tiempo)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Estafa por WhatsApp con nombre de YouTube: empleo de medio tiempo con ganancias sustanciosas por hacer clic en enlaces indicados por el estafador.', NULL, FALSE, 'fraude_economico', 'medium', 3),
 ('PRESS-0017', NULL, NULL, 'secretaria', NULL, NULL, NULL, NULL, 'Soria, España', NULL, 'como validación de identidad y reserva de entrevista', 'Anuncio falso en InfoJobs para secretaria en Soria pedía DNI, vida laboral y una transferencia de 0,01 euros para obtener datos bancarios y suplantar identidad.', 'IdentityTheftScheme', FALSE, 'fraude_economico', 'high', 1),
 ('PRESS-0018', (SELECT country_code FROM countries WHERE country_iso3 = 'ESP'), (SELECT platform_id FROM platforms WHERE platform_name = 'Telegram'), 'puesto remoto con salario por trabajo sencillo', NULL, NULL, NULL, NULL, NULL, NULL, 'trabajo sencillo', 'Mensaje que suplanta a InfoJobs ofrece puesto remoto con salario por un trabajo sencillo y pide contactar por Telegram; InfoJobs confirmó que es suplantación.', NULL, FALSE, 'fraude_economico', 'medium', 1),
 ('PRESS-0019', (SELECT country_code FROM countries WHERE country_iso3 = 'ESP'), NULL, 'empleados online a tiempo parcial', NULL, NULL, NULL, NULL, NULL, NULL, 'urgentemente a 30 empleados online a tiempo parcial', 'SMS falso a nombre de InfoJobs que solicita urgentemente 30 empleados online a tiempo parcial.', NULL, FALSE, NULL, 'medium', 1),
 ('PRESS-0020', (SELECT country_code FROM countries WHERE country_iso3 = 'MEX'), (SELECT platform_id FROM platforms WHERE platform_name = 'WhatsApp'), 'dar likes y seguir cuentas en TikTok', NULL, NULL, NULL, NULL, NULL, NULL, 'Su hoja de vida ha sido seleccionada para una oferta laboral. Comuníquese con nosotros para acceder a esta oportunidad.', 'Llamada robótica o mensajes de WhatsApp ofrecen pagar por dar likes y seguir cuentas de TikTok; la víctima termina invirtiendo sumas crecientes y pierde todo.', 'PayToWorkScheme', FALSE, 'fraude_economico', 'high', 1),
 ('PRESS-0021', NULL, NULL, 'vacantes en el Tren Maya', NULL, NULL, NULL, NULL, 'Tren Maya', NULL, NULL, 'Falsa oferta de trabajo en el Tren Maya pide enviar CV y comprobante de estudios a correos electrónicos; después nadie responde.', 'IdentityTheftScheme', FALSE, 'fraude_economico', 'medium', 1),
 ('PRESS-0022', NULL, NULL, 'oferta laboral por currículum aprobado', NULL, NULL, NULL, NULL, NULL, NULL, 'Por favor agregue mis datos de contacto: wa.me/573194625582.', 'SMS dice que aprobaron el currículum y promete sueldo atractivo, e indica agregar un contacto de WhatsApp (+57) para continuar.', NULL, FALSE, 'fraude_economico', 'medium', 1),
 ('PRESS-0023', NULL, (SELECT platform_id FROM platforms WHERE platform_name = 'WhatsApp'), 'tareas en TikTok', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Falsa oferta de TikTok por WhatsApp: tareas con captura de pantalla, un pago pequeño inicial y luego depósito en garantía por Telegram antes de pagar lo acumulado.', 'PayToWorkScheme', FALSE, 'fraude_economico', 'high', 1),
 ('PRESS-0024', NULL, (SELECT platform_id FROM platforms WHERE platform_name = 'WhatsApp'), 'tareas de YouTube (empresa ''YOUTUBER'')', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Empresa inexistente ''YOUTUBER'' recluta por WhatsApp para tareas; tras acumular tareas piden un fee de $20.000 antes de transferir el pago y desaparecen.', 'PayToWorkScheme', FALSE, 'fraude_economico', 'high', 1),
 ('PRESS-0025', (SELECT country_code FROM countries WHERE country_iso3 = 'ARG'), (SELECT platform_id FROM platforms WHERE platform_name = 'Facebook'), 'trabajo desde el teléfono (sin experiencia, 15-20 minutos diarios)', 20000, 'ARS', NULL, NULL, NULL, NULL, NULL, 'Anuncio de Facebook ofrecía trabajo sin experiencia, 15-20 minutos diarios, por 20.000 a 30.000 pesos (unos 80 USD); la víctima argentina perdió el dinero invertido.', 'PyramidScheme', FALSE, 'fraude_economico', 'high', 2),
 ('PRESS-0026', (SELECT country_code FROM countries WHERE country_iso3 = 'ARG'), NULL, 'tareas suplantando a Mercado Libre (anuncio en app de empleo de dudosa reputación)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Una persona de Colombia llegó a los estafadores por un anuncio en una app de empleo dudosa y videos que suplantaban a Mercado Libre.', 'PyramidScheme', FALSE, 'fraude_economico', 'low', 2),
 ('PRESS-0027', (SELECT country_code FROM countries WHERE country_iso3 = 'MEX'), NULL, 'vigilante de seguridad', 4000, 'MXN', 'semanal', 4000, NULL, NULL, NULL, 'Reclutador ofrecía por redes sociales vacantes de vigilante con sueldos de 4 mil a 12 mil pesos semanales; citaba en centrales de autobuses y llevaba al Rancho Izaguirre.', 'ForcedCriminalityScheme', TRUE, 'desaparicion', 'high', 2),
 ('PRESS-0028', NULL, NULL, 'tareas sencillas para supuesta empresa de Amazon', 2000, 'ARS', NULL, NULL, NULL, NULL, NULL, 'Sitios en anuncios de Google atraen con ''empleo sin experiencia''; reclutadora ''Sofía Astuta'' dice ser de Amazon, promete 2000 ARS al registrarse y pide captura de pantalla.', 'OnlineCryptoJobScheme', FALSE, 'fraude_economico', 'medium', 1),
 ('PRESS-0029', NULL, NULL, 'dar compañía y atender a caballeros en bares', NULL, NULL, NULL, NULL, 'Puerto Maldonado, Madre de Dios, Perú', 'jóvenes mujeres', 'dar compañía y atender a caballeros en bares', 'Dos jóvenes de Lambayeque recibieron oferta en redes de empleo en Puerto Maldonado con gastos pagados, que luego resultó ser dar compañía a caballeros en bares.', NULL, FALSE, NULL, 'high', 1),
 ('PRESS-0030', (SELECT country_code FROM countries WHERE country_iso3 = 'MEX'), NULL, 'modelo', 500, 'MXN', 'por_tarea', NULL, 'Puebla', 'mujeres jóvenes', NULL, 'Oferta en redes sociales para ser modelo en Puebla con salario de 500 pesos por evento; en la ''entrevista'' la joven fue agredida sexualmente por un grupo de hombres.', 'ModelingAgencyScheme', FALSE, 'other', 'medium', 1),
 ('PRESS-0031', (SELECT country_code FROM countries WHERE country_iso3 = 'ECU'), (SELECT platform_id FROM platforms WHERE platform_name = 'Facebook'), 'ayudante de panadería', NULL, NULL, NULL, NULL, NULL, 'mujeres jóvenes, entre ellas una adolescente', NULL, 'Red anunciaba en Facebook trabajos de ayudante de panadería; las jóvenes aceptaban y eran llevadas a hoteles de Ambato y Riobamba para explotación sexual.', NULL, FALSE, 'explotacion_sexual', 'high', 1),
 ('PRESS-0032', (SELECT country_code FROM countries WHERE country_iso3 = 'MEX'), (SELECT platform_id FROM platforms WHERE platform_name = 'Facebook'), 'edecán en la Feria de Puebla', 2000, 'MXN', NULL, NULL, 'Feria de Puebla', 'mujeres, estudiantes', NULL, 'Perfil falso en grupos de empleo de Facebook ofrece 2 mil pesos por tres días como edecán en la Feria de Puebla, sin experiencia, y cita en lugares poco concurridos.', 'InPersonLureScheme', FALSE, NULL, 'high', 1),
 ('PRESS-0033', (SELECT country_code FROM countries WHERE country_iso3 = 'USA'), (SELECT platform_id FROM platforms WHERE platform_name = 'WhatsApp'), 'empleado a tiempo parcial desde casa (TikTok)', 40, 'EUR', 'diario', NULL, NULL, NULL, 'Estamos buscando reclutar a 5,000 empleados a tiempo parcial', 'Mensaje falso del ''departamento de promoción de TikTok'' ofrece trabajo desde casa desde 40 euros diarios y 5 euros inmediatos; el enlace lleva a WhatsApp.', NULL, FALSE, 'fraude_economico', 'high', 1),
 ('PRESS-0034', (SELECT country_code FROM countries WHERE country_iso3 = 'MEX'), (SELECT platform_id FROM platforms WHERE platform_name = 'CompuTrabajo'), 'edecán, modelo u hostess', 11000, 'MXN', 'mensual', NULL, 'Puebla', 'mujeres de 18 a 22 años, universitarias foráneas', NULL, 'Vacantes de edecán, modelo u hostess por 11 a 15 mil pesos mensuales con horario flexible para mujeres de 18 a 22 años; piden fotos de cuerpo completo y luego presionan para trabajo sexual.', 'ModelingAgencyScheme', FALSE, 'explotacion_sexual', 'high', 1),
 ('PRESS-0035', (SELECT country_code FROM countries WHERE country_iso3 = 'ARG'), (SELECT platform_id FROM platforms WHERE platform_name = 'WhatsApp'), 'trabajo desde casa / trabajo online', NULL, NULL, NULL, NULL, NULL, NULL, 'Has sido seleccionado para una oferta de trabajo desde casa', 'Mensajes por WhatsApp, Telegram y SMS dicen ''has sido seleccionado'' para trabajo desde casa, suplantando a empresas como Mercado Libre, y piden datos y pagos administrativos.', 'PayToWorkScheme', FALSE, 'fraude_economico', 'medium', 1),
 ('PRESS-0036', NULL, NULL, 'transportista socio de cooperativa de transporte', 1800, 'EUR', 'mensual', NULL, NULL, NULL, NULL, 'Empresario simuló una cooperativa de transporte y ofreció a transportistas unos 1.800 euros al mes, haciéndolos autónomos sin saberlo; fue condenado por estafa y delito contra derechos laborales.', NULL, FALSE, 'fraude_economico', 'medium', 1),
 ('PRESS-0037', NULL, (SELECT platform_id FROM platforms WHERE platform_name = 'WhatsApp'), 'oferta de empleo por WhatsApp', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Llamada grabada que suplanta a InfoJobs invita a escribir por WhatsApp para recibir información sobre una oferta de empleo; InfoJobs la califica de estafa.', NULL, FALSE, 'fraude_economico', 'medium', 1),
 ('PRESS-0038', NULL, NULL, 'ayudante de desarrolladores de apps', NULL, NULL, NULL, NULL, NULL, NULL, 'desarrolladores de apps', 'Mensaje fraudulento ofrecía un puesto como ayudante de ''desarrolladores de apps'' suplantando a InfoJobs.', NULL, FALSE, NULL, 'low', 1),
 ('PRESS-0039', (SELECT country_code FROM countries WHERE country_iso3 = 'MEX'), NULL, 'guardia de seguridad', 13000, 'MXN', 'mensual', NULL, NULL, NULL, NULL, 'Sobreviviente del Rancho Izaguirre dijo que hacia junio de 2024 vio oferta de guardia de seguridad por 13 mil pesos al mes y acudió a la cita en la terminal de autobuses de Tlaquepaque.', 'ForcedCriminalityScheme', TRUE, 'explotacion_laboral', 'high', 1),
 ('PRESS-0040', (SELECT country_code FROM countries WHERE country_iso3 = 'COL'), (SELECT platform_id FROM platforms WHERE platform_name = 'WhatsApp'), 'oferta de empleo de McDonald''s', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Estafadores usan el nombre de McDonald''s en Colombia para contactar por WhatsApp y pedir dinero por exámenes médicos y certificados inexistentes.', 'PayToWorkScheme', FALSE, 'fraude_economico', 'medium', 1),
 ('PRESS-0041', NULL, NULL, 'puesto de poca responsabilidad y muy buena remuneración', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Correo de falso departamento de RR.HH. ofrece un puesto de poca responsabilidad y muy buena remuneración, con horario y salario detallados, y pide responder.', 'IdentityTheftScheme', FALSE, 'fraude_economico', 'low', 1),
 ('PRESS-0042', (SELECT country_code FROM countries WHERE country_iso3 = 'ARG'), (SELECT platform_id FROM platforms WHERE platform_name = 'Instagram'), 'vender productos para Shopee', 50000, 'ARS', 'diario', NULL, NULL, NULL, NULL, 'Grupo de difusión en Instagram con falso Director de Contratación de Shopee ofrece 50.000 a 200.000 pesos argentinos por día y 1200 pesos al registrarse en un enlace inseguro.', 'OnlineInfluencerSalesScheme', FALSE, 'fraude_economico', 'high', 1),
 ('PRESS-0043', (SELECT country_code FROM countries WHERE country_iso3 = 'USA'), NULL, 'trabajo en plataformas petroleras o buques cisterna', 5000, 'USD', 'mensual', NULL, 'Caribe y buques cisterna en el continente', NULL, NULL, 'Avisos falsos en portales web de Venezuela a nombre de BP o Shell ofrecen trabajo en plataformas petroleras con más de 5000 USD al mes y exigen pagos antes de comenzar.', 'PayToWorkScheme', FALSE, 'fraude_economico', 'high', 1),
 ('PRESS-0044', (SELECT country_code FROM countries WHERE country_iso3 = 'COL'), (SELECT platform_id FROM platforms WHERE platform_name = 'Facebook'), 'varios puestos en Almacenes Éxito', NULL, NULL, NULL, NULL, 'Cali, Bucaramanga, Medellín, Ibagué y Bogotá', NULL, NULL, 'Publicación de Facebook con vacantes falsas de Almacenes Éxito en Cali y otras ciudades para recolectar hojas de vida y datos con los que suplantar identidades.', 'IdentityTheftScheme', FALSE, 'fraude_economico', 'high', 1),
 ('PRESS-0045', (SELECT country_code FROM countries WHERE country_iso3 = 'MEX'), NULL, 'oferta de trabajo en México (sin detalle)', NULL, NULL, NULL, NULL, 'México', NULL, NULL, 'Una argentina residente en Buenos Aires viajó a México en junio por una oferta de trabajo que resultó ser trata de personas; fue rescatada tras una investigación.', NULL, FALSE, 'rescate', 'low', 1),
 ('PRESS-0046', (SELECT country_code FROM countries WHERE country_iso3 = 'ESP'), (SELECT platform_id FROM platforms WHERE platform_name = 'Facebook'), 'vacantes en Mercadona (580 plazas)', NULL, NULL, NULL, NULL, NULL, NULL, 'Gran convocatoria. Pueden postular personas mayores de 18 años con o sin experiencia. 580 plazas disponibles', 'Post de Facebook con falsa convocatoria de Mercadona para 580 plazas, con o sin experiencia, que enlaza a una web de phishing.', 'IdentityTheftScheme', FALSE, 'fraude_economico', 'high', 1),
 ('PRESS-0047', (SELECT country_code FROM countries WHERE country_iso3 = 'ESP'), (SELECT platform_id FROM platforms WHERE platform_name = 'WhatsApp'), 'cajero o auxiliar de limpieza en Mercadona', NULL, NULL, NULL, NULL, NULL, NULL, 'contratando con urgencia', 'Cadena de WhatsApp dice que Mercadona está contratando con urgencia, incluso sin experiencia, cajeros y auxiliares de limpieza para un nuevo local; es phishing.', 'IdentityTheftScheme', FALSE, 'fraude_economico', 'high', 1),
 ('PRESS-0048', (SELECT country_code FROM countries WHERE country_iso3 = 'ESP'), (SELECT platform_id FROM platforms WHERE platform_name = 'Facebook'), '200 trabajadores en Mercadona', 1780, 'EUR', NULL, NULL, NULL, NULL, NULL, 'Perfil de Facebook ''Empleate España'' difundía cartel falso de Mercadona para 200 trabajadores con sueldo por encima de 1780 euros; era phishing.', 'IdentityTheftScheme', FALSE, 'fraude_economico', 'low', 1),
 ('PRESS-0049', NULL, (SELECT platform_id FROM platforms WHERE platform_name = 'WhatsApp'), 'reseñas (Google Maps o YouTube) de medio tiempo', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ESET advierte de estafa por WhatsApp con nombre de Google Maps o YouTube que ofrece empleo de medio tiempo para hacer reseñas a cambio de comisiones.', NULL, FALSE, 'fraude_economico', 'medium', 1),
 ('PRESS-0050', (SELECT country_code FROM countries WHERE country_iso3 = 'MEX'), NULL, 'empleo en empresa de telefonía', NULL, NULL, NULL, NULL, 'Área Metropolitana de Guadalajara, Jalisco', 'joven mujer', NULL, 'Joven de Zacatecas viajó a Guadalajara por oferta en redes de empleo inmediato en una empresa de telefonía con apoyo de traslado y hospedaje; escapó al llegar.', 'InPersonLureScheme', FALSE, 'rescate', 'high', 1),
