 ('PRESS-0336', (SELECT country_code FROM countries WHERE country_iso3 = 'CHL'), (SELECT platform_id FROM platforms WHERE platform_name = 'TikTok'), NULL, NULL, NULL, NULL, NULL, 'Ecuador', 'mujer colombiana', NULL, 'Mujer colombiana conoció en TikTok a ''Kevin'', quien le ofreció empleo y mejores ingresos en Ecuador; dejó de comunicarse y fue rescatada.', NULL, FALSE, 'rescate', 'high', 2),
 ('PRESS-0337', (SELECT country_code FROM countries WHERE country_iso3 = 'CHL'), NULL, 'modelaje', NULL, NULL, NULL, NULL, 'Antofagasta, Chile', 'mujer colombiana', NULL, 'Otra colombiana fue engañada con falsas ofertas de modelaje y rescatada en Antofagasta, Chile, donde las condiciones eran de comercio sexual.', 'ModelingAgencyScheme', FALSE, 'explotacion_sexual', 'medium', 1),
 ('PRESS-0338', (SELECT country_code FROM countries WHERE country_iso3 = 'COL'), NULL, NULL, NULL, NULL, NULL, NULL, 'Oslo, Noruega', 'jóvenes en condición de vulnerabilidad', NULL, 'Red captaba jóvenes de Cali con ofertas laborales de jugosos sueldos para viajar a Oslo, donde las explotaban sexualmente.', NULL, FALSE, 'explotacion_sexual', 'medium', 2),
 ('PRESS-0339', (SELECT country_code FROM countries WHERE country_iso3 = 'PER'), NULL, 'agente de seguridad y otras funciones', NULL, NULL, NULL, NULL, 'Rusia', 'exmilitares y expolicías', NULL, 'Exmilitares y expolicías peruanos captados en redes con ofertas engañosas de agente de seguridad en Rusia fueron obligados a combatir en Ucrania.', NULL, FALSE, 'explotacion_laboral', 'medium', 1),
 ('PRESS-0340', (SELECT country_code FROM countries WHERE country_iso3 = 'COL'), NULL, 'empleo bien remunerado (tipo de trabajo similar al de Lima)', 3000, 'USD', 'mensual', NULL, 'Rusia', 'hombres y mujeres de 18 a 65 años, incluso familias', NULL, 'Promesas de empleos bien pagados con pago inicial de hasta 20 mil dólares y sueldos de 3 a 4 mil dólares mensuales; hay 73 peruanos desaparecidos en la guerra.', NULL, FALSE, 'desaparicion', 'high', 1),
 ('PRESS-0341', (SELECT country_code FROM countries WHERE country_iso3 = 'PER'), NULL, 'agente de seguridad y otras labores', NULL, NULL, NULL, NULL, 'Rusia', NULL, NULL, 'Peruanos captados con falsas ofertas para trabajar como agentes de seguridad en Rusia, donde fueron obligados a participar en combate.', NULL, FALSE, 'explotacion_laboral', 'medium', 1),
 ('PRESS-0343', (SELECT country_code FROM countries WHERE country_iso3 = 'ECU'), NULL, NULL, NULL, NULL, NULL, NULL, 'Iquitos, Loreto', 'jóvenes y menores indígenas', NULL, 'Entre seis y ocho jóvenes indígenas Chapra fueron trasladados a Iquitos con ofertas laborales engañosas y rescatados de explotación en tala ilegal.', NULL, FALSE, 'rescate', 'medium', 1),
 ('PRESS-0344', (SELECT country_code FROM countries WHERE country_iso3 = 'ECU'), (SELECT platform_id FROM platforms WHERE platform_name = 'Facebook'), NULL, NULL, NULL, NULL, NULL, 'Iquitos, Loreto', 'menor indígena', NULL, 'Una menor awajún fue contactada por Facebook con falsas ofertas de empleo y trasladada engañada a Iquitos; logró huir semanas después.', NULL, FALSE, 'desaparicion', 'medium', 1),
 ('PRESS-0345', (SELECT country_code FROM countries WHERE country_iso3 = 'PER'), NULL, NULL, NULL, NULL, NULL, NULL, 'Madre de Dios, Perú', 'adolescentes y jóvenes', NULL, 'Adolescentes y jóvenes llegan a Madre de Dios atraídas por falsas convocatorias y promesas de altos sueldos y caen en manos de tratantes.', NULL, FALSE, NULL, 'low', 1),
 ('PRESS-0346', (SELECT country_code FROM countries WHERE country_iso3 = 'ECU'), NULL, NULL, NULL, NULL, NULL, NULL, 'Tambogrande, Piura, Perú', NULL, NULL, 'Falsas ofertas de empleo difundidas en calles, redes y parlantes móviles en caseríos de Piura llevan a víctimas de trata a bares y cantinas.', NULL, FALSE, NULL, 'low', 1),
 ('PRESS-0347', (SELECT country_code FROM countries WHERE country_iso3 = 'MEX'), NULL, 'empleo en el sector turístico', NULL, NULL, NULL, NULL, 'Cancún, Quintana Roo', 'mujeres', NULL, 'Una cubana y un argentino ofrecían a mujeres empleo turístico en Cancún con boleto de avión, hospedaje y buena paga; al llegar las obligaban a dar servicios sexuales.', NULL, FALSE, 'explotacion_sexual', 'high', 1),
 ('PRESS-0348', (SELECT country_code FROM countries WHERE country_iso3 = 'ARG'), NULL, NULL, NULL, NULL, NULL, NULL, 'Buenos Aires, Argentina', NULL, NULL, 'Red ofrecía trabajo y alojamiento en Argentina, cubría traslado y estadía como deuda, retenía documentos y obligaba a vender muebles en la calle para pagarla.', 'DebtBondageTraffickingScheme', FALSE, 'explotacion_laboral', 'high', 1),
 ('PRESS-0349', (SELECT country_code FROM countries WHERE country_iso3 = 'CHL'), NULL, 'trabajo en una mina de oro', 2000000, 'CLP', NULL, NULL, 'Mariquina, Los Ríos, Chile', 'cinco exmilitares chinos', NULL, 'Cinco exmilitares chinos contactados por un compatriota para trabajar en una mina de oro en Mariquina con sueldo cercano a 2 millones de pesos; vivieron dos años sin pago.', NULL, FALSE, 'explotacion_laboral', 'high', 1),
 ('PRESS-0350', (SELECT country_code FROM countries WHERE country_iso3 = 'ECU'), NULL, 'empleo en el extranjero (ej. Finlandia)', NULL, NULL, NULL, NULL, 'Finlandia (destino final Camboya)', NULL, NULL, 'Red captaba ecuatorianos con ofertas laborales en el extranjero, a veces Finlandia, y los enviaba a Camboya a trabajar en centros de estafas informáticas.', 'ForcedCriminalityScheme', TRUE, 'explotacion_laboral', 'high', 2),
 ('PRESS-0351', (SELECT country_code FROM countries WHERE country_iso3 = 'ECU'), NULL, NULL, NULL, NULL, NULL, NULL, 'Camboya', NULL, NULL, 'Seis detenidos por captar con ofertas fraudulentas y contratos simulados a víctimas enviadas a ''call centers'' clandestinos en Camboya.', 'ForcedCriminalityScheme', TRUE, 'explotacion_laboral', 'medium', 1),
 ('PRESS-0352', (SELECT country_code FROM countries WHERE country_iso3 = 'BRA'), NULL, 'modelo', NULL, NULL, NULL, NULL, 'Guayaquil, Ecuador', 'mujeres vulnerables de 17 a 26 años', NULL, 'Un hombre de 21 años ofrecía dinero a mujeres de 17 a 26 años para trabajar como modelos en Guayaquil y luego las obligaba a prostituirse.', 'ModelingAgencyScheme', FALSE, 'explotacion_sexual', 'high', 1)
